const buildClientResult = node({
  type: 'n8n-nodes-base.code', version: 2,
  config: { name: 'Build Curated Client Result', parameters: { mode: 'runOnceForAllItems', language: 'javaScript', jsCode: "// FINMENTOR X-Ray Analysis — \"Build Curated Client Result\".\n//\n// Runs ONLY on the promotion branch (PROMOTE, or ALREADY_READY as an idempotent repair). Emits\n// exactly one row for the n8n Data Table `XRay_Client_Results`, which is the ONLY store the Mini\n// App Gateway reads for the customer result — upserted by lead_id, so a lead has one published\n// result and re-promotion replaces it.\n//\n// CURATED. result_json carries the customer-facing analysis and nothing else: locale, product\n// labels, score, zone, maturity, key risks, management priorities, the 30-day plan, tomorrow's\n// actions and the FINMENTOR recommendation. No review token, no raw model response, no owner\n// notes, no prompt, no request id, no confidence/fabrication internals, no AI_DRAFT or\n// ANALYSIS_FAILED — a draft or failed row never reaches this node (the verdict refuses them).\n\nconst v = $('Review POST Verdict').first().json || {};\nconst row = v.source_row || {};\nif (v.proceed_update !== true || String(row.review_status || '') === 'ANALYSIS_FAILED' || String(row.lead_id || '') === '') return [];\nlet a = null; try { a = JSON.parse(String(row.analysis_json || 'null')); } catch (e) { a = null; }\nif (!a || typeof a !== 'object' || Array.isArray(a)) return [];\n\nconst locale = row.locale === 'ro' ? 'ro' : 'ru';\nconst labels = locale === 'ro'\n  ? { product: 'Radiografia Financiară FINMENTOR', condition: 'Starea financiară', score: 'Scor', zone: 'Zona de risc', maturity: 'Maturitatea managementului financiar', risks: 'Riscuri-cheie', priorities: 'Priorități de management', plan: 'Plan de acțiune financiară pentru 30 de zile', tomorrow: 'Următoarea acțiune', next: 'Recomandarea FINMENTOR' }\n  : { product: 'Финансовый рентген бизнеса', condition: 'Финансовое состояние', score: 'Оценка', zone: 'Зона риска', maturity: 'Зрелость финансового управления', risks: 'Ключевые риски', priorities: 'Приоритеты управления', plan: 'План финансовых действий на 30 дней', tomorrow: 'Следующее действие', next: 'Рекомендация FINMENTOR' };\nconst zones = locale === 'ro'\n  ? { GREEN: 'Zonă verde', YELLOW: 'Zonă galbenă', ORANGE: 'Zonă portocalie', RED: 'Zonă roșie', UNKNOWN: 'Fără scor' }\n  : { GREEN: 'Зелёная зона', YELLOW: 'Жёлтая зона', ORANGE: 'Оранжевая зона', RED: 'Красная зона', UNKNOWN: 'Без оценки' };\nconst zone = ['GREEN', 'YELLOW', 'ORANGE', 'RED', 'UNKNOWN'].includes(String(row.zone)) ? String(row.zone) : 'UNKNOWN';\nconst str = (x, n) => String(x == null ? '' : x).slice(0, n || 600);\nconst action = (x) => x && typeof x === 'object' ? { action: str(x.action, 300), owner_role: str(x.owner_role, 80), expected_output: str(x.expected_output, 300), control_or_kpi: str(x.control_or_kpi, 200), priority: str(x.priority, 10) } : null;\nconst week = (w) => (Array.isArray(w) ? w : []).map(action).filter(Boolean).slice(0, 6);\n\nconst result = {\n  locale,\n  labels,\n  score: row.score === '' || row.score === undefined || row.score === null ? null : Number(row.score),\n  zone,\n  zone_label: zones[zone],\n  maturity: a.financial_maturity && typeof a.financial_maturity === 'object'\n    ? { score_1_to_5: a.financial_maturity.score_1_to_5, label: str(a.financial_maturity.label, 120), rationale: str(a.financial_maturity.rationale, 800) }\n    : null,\n  summary: str(a.executive_summary, 2500),\n  key_risks: (Array.isArray(a.key_risks) ? a.key_risks : []).map(r => r && typeof r === 'object' ? { title: str(r.title, 160), category: str(r.category, 80), evidence: str(r.evidence, 500), potential_impact: str(r.potential_impact, 500), priority: str(r.priority, 10) } : null).filter(Boolean).slice(0, 5),\n  management_priorities: (Array.isArray(a.management_priorities) ? a.management_priorities : []).map(p => str(p, 300)).slice(0, 3),\n  plan_30_days: {\n    days_1_7: week((a.plan_30_days || {}).days_1_7), days_8_14: week((a.plan_30_days || {}).days_8_14),\n    days_15_21: week((a.plan_30_days || {}).days_15_21), days_22_30: week((a.plan_30_days || {}).days_22_30)\n  },\n  tomorrow_actions: (Array.isArray(a.tomorrow_actions) ? a.tomorrow_actions : []).map(p => str(p, 300)).slice(0, 3),\n  recommended_next_step: a.recommended_next_step && typeof a.recommended_next_step === 'object'\n    ? { product: str(a.recommended_next_step.product, 40), label: str(a.recommended_next_step.label, 160), rationale: str(a.recommended_next_step.rationale, 600) }\n    : null\n};\n\n// The Data Table row: exactly the live columns of XRay_Client_Results.\nreturn [{ json: {\n  analysis_id: String(row.analysis_id || ''),\n  lead_id: String(row.lead_id || ''),\n  locale,\n  published_at: new Date().toISOString(),\n  result_json: JSON.stringify(result),\n  review_status: 'CLIENT_READY',\n  score: result.score === null ? '' : String(result.score),\n  zone\n} }];\n" } },
  output: [{ analysis_id: '', lead_id: '', locale: 'ru', published_at: '', result_json: '{}', review_status: 'CLIENT_READY', score: '', zone: '' }]
});

const publishClientResult = node({
  type: 'n8n-nodes-base.dataTable', version: 1.1,
  config: { name: 'Publish Curated Client Result', retryOnFail: true,
    parameters: { resource: 'row', operation: 'upsert', dataTableId: { __rl: true, mode: 'name', value: "XRay_Client_Results" },
      matchType: 'allConditions', filters: { conditions: [{ keyName: 'lead_id', condition: 'eq', keyValue: expr('{{ $json.lead_id }}') }] },
      columns: { mappingMode: 'autoMapInputData', value: {}, matchingColumns: [], schema: [] }, options: {} } },
  output: [{ lead_id: '', review_status: 'CLIENT_READY' }]
});

const respondPromoted = node({
  type: 'n8n-nodes-base.respondToWebhook', version: 1.5,
  config: { name: 'Respond Review Done', parameters: { respondWith: 'text', responseBody: expr("{{ $('Review POST Verdict').item.json.html }}"),
    options: { responseCode: 200, responseHeaders: { entries: [{ name: 'Content-Type', value: 'text/html; charset=utf-8' }, { name: 'Cache-Control', value: 'no-store' }, { name: 'Referrer-Policy', value: 'no-referrer' }, { name: 'X-Robots-Tag', value: 'noindex, nofollow' }] } } } },
  output: [{}]
});

// ✅ Анализ подтверждён — ONE owner message on the FIRST promotion only (OWNER DECISION 2026-09-04,
// A5: a second notification only for a real state transition). Placed AFTER the HTTP response so
// the owner's browser is never kept waiting on Telegram; a repeated confirmation (ALREADY_READY)
// carries notify_owner false and reaches no Telegram node. Same chat, same credential as the
// review card; nothing else in the promotion chain moves.
const ifFirstPromotion = ifElse({
  version: 2.2,
  config: { name: 'IF First Promotion', parameters: { conditions: { options: { caseSensitive: true, leftValue: '', typeValidation: 'strict' },
    conditions: [{ leftValue: expr("{{ $('Review POST Verdict').item.json.notify_owner }}"), operator: { type: 'boolean', operation: 'true', singleValue: true } }], combinator: 'and' } } }
});

const ownerApprovedNotice = node({
  type: 'n8n-nodes-base.telegram', version: 1.2,
  config: { name: 'Telegram Analysis Approved', onError: 'continueRegularOutput',
    parameters: { resource: 'message', operation: 'sendMessage',
      chatId: expr("{{ $('Settings to Object').first().json.settings.owner_chat_id }}"),
      text: expr("{{ $('Review POST Verdict').item.json.owner_approved_text }}"),
      additionalFields: { appendAttribution: false, parse_mode: 'HTML', disable_web_page_preview: true } },
    credentials: { telegramApi: { id: 'Mj41qrGHfrthCtAw', name: 'FINMENTOR Leads Bot FINAL' } } },
  output: [{ ok: true }]
});

const respondDenied = node({
  type: 'n8n-nodes-base.respondToWebhook', version: 1.5,
  config: { name: 'Respond Review Denied', parameters: { respondWith: 'text', responseBody: expr('{{ $json.html }}'),
    options: { responseCode: expr('{{ $json.http_status }}'), responseHeaders: { entries: [{ name: 'Content-Type', value: 'text/html; charset=utf-8' }, { name: 'Cache-Control', value: 'no-store' }, { name: 'Referrer-Policy', value: 'no-referrer' }, { name: 'X-Robots-Tag', value: 'noindex, nofollow' }] } } } },
  output: [{}]
});

export default workflow('finmentor-xray-analysis', 'FINMENTOR X-Ray Analysis')
  .add(sweepTrigger)
  .to(readSettings)
  .to(settingsToObject)
  .to(readPipeline)
  .to(readAnalysis)
  .to(selectPending)
  .to(readLeadRaw)
  .to(buildInput)
  .to(aiAnalysis
    .onError(failedRowBuild.to(failedRow.to(saveFailed.to(ownerFailureNotice)))))
  .to(validateRows)
  .to(analysisRow)
  .to(saveAnalysis)
  .to(pipelineRow)
  .to(updatePipeline)
  .to(ifAnalysisValid
    .onTrue(ownerAlert)
    .onFalse(validationFailureNotice))
  .add(reviewGetWebhook)
  .to(readForReviewGet)
  .to(reviewSurface)
  .to(respondReviewSurface)
  .add(reviewPostWebhook)
  .to(readForReviewPost)
  .to(reviewVerdict)
  .to(ifPromote
    .onTrue(promoteRow.to(promoteAnalysis.to(pipelineStatusRow.to(updatePipelineStatus.to(buildClientResult.to(publishClientResult.to(respondPromoted.to(ifFirstPromotion.onTrue(ownerApprovedNotice)))))))))
    .onFalse(respondDenied));
